import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Plus, Check, Trash2 } from 'lucide-react';
import { useWorkspaceStore } from '../../store/useWorkspaceStore';

export default function CorkBoard() {
  const { todos, addTodo, toggleTodo, deleteTodo, updateTodoPosition } = useWorkspaceStore();
  const [inputText, setInputText] = useState('');
  const [selectedColor, setSelectedColor] = useState('yellow');

  const colorStyles = {
    yellow: 'bg-[var(--color-sticky-yellow)] text-amber-950',
    pink: 'bg-[var(--color-sticky-pink)] text-rose-950',
    blue: 'bg-[var(--color-sticky-blue)] text-cyan-950',
    green: 'bg-[var(--color-sticky-green)] text-emerald-950',
  };

  const handleCreate = (e) => {
    e.preventDefault();
    if (!inputText.trim()) return;
    addTodo(inputText, selectedColor);
    setInputText('');
  };

  return (
    <div className="relative w-full h-[calc(100vh-80px)] bg-[var(--color-cork)] border-[12px] border-[var(--color-cork-border)] rounded-2xl shadow-2xl overflow-hidden p-6 select-none">
      {/* Wooden Frame Top Toolbar */}
      <div className="absolute top-4 left-6 z-20 flex items-center gap-3 bg-white/80 backdrop-blur-md px-4 py-2 rounded-xl shadow-md border border-amber-200">
        <form onSubmit={handleCreate} className="flex items-center gap-2">
          <input
            type="text"
            placeholder="Stick a new task..."
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            className="px-3 py-1.5 text-sm bg-transparent outline-none border-b border-amber-400 font-medium text-stone-800 placeholder-stone-500 w-56"
          />
          <div className="flex gap-1.5 px-2">
            {['yellow', 'pink', 'blue', 'green'].map((color) => (
              <button
                key={color}
                type="button"
                onClick={() => setSelectedColor(color)}
                className={`w-5 h-5 rounded-full border border-black/20 transition-transform ${
                  color === 'yellow' ? 'bg-[#fff37a]' :
                  color === 'pink' ? 'bg-[#ff8fab]' :
                  color === 'blue' ? 'bg-[#8ae9ff]' : 'bg-[#bbf7d0]'
                } ${selectedColor === color ? 'scale-125 ring-2 ring-stone-700' : ''}`}
              />
            ))}
          </div>
          <button
            type="submit"
            className="flex items-center gap-1 bg-stone-800 hover:bg-stone-900 text-white px-3 py-1.5 rounded-lg text-xs font-semibold tracking-wide transition shadow"
          >
            <Plus size={14} /> Pin
          </button>
        </form>
      </div>

      {/* Free-drag Area for Sticky Notes */}
      <div className="relative w-full h-full">
        {todos.map((todo) => (
          <motion.div
            key={todo.id}
            drag
            dragMomentum={false}
            onDragEnd={(_, info) => {
              updateTodoPosition(todo.id, todo.x + info.offset.x, todo.y + info.offset.y);
            }}
            initial={{ scale: 0, rotate: 0 }}
            animate={{ scale: 1, rotate: todo.rotation }}
            className={`absolute w-52 min-h-[140px] p-4 rounded-sm shadow-[var(--shadow-sticky)] cursor-grab active:cursor-grabbing flex flex-col justify-between ${colorStyles[todo.color]}`}
            style={{ left: `${todo.x}px`, top: `${todo.y}px` }}
          >
            {/* Push Pin Visual */}
            <div className="absolute -top-3 left-1/2 -translate-x-1/2 w-4 h-4 rounded-full bg-red-600 shadow-md border border-white flex items-center justify-center">
              <div className="w-1.5 h-1.5 rounded-full bg-red-300"></div>
            </div>

            <p className={`font-medium text-sm leading-relaxed mt-2 ${todo.completed ? 'line-through opacity-50 decoration-2 decoration-red-500' : ''}`}>
              {todo.text}
            </p>

            <div className="flex items-center justify-between pt-2 border-t border-black/10 mt-3">
              <button
                onClick={() => toggleTodo(todo.id)}
                className={`p-1 rounded hover:bg-black/10 transition ${todo.completed ? 'text-emerald-700' : 'text-stone-700'}`}
              >
                <Check size={16} />
              </button>
              <button
                onClick={() => deleteTodo(todo.id)}
                className="p-1 rounded text-stone-500 hover:text-rose-700 hover:bg-black/10 transition"
              >
                <Trash2 size={15} />
              </button>
            </div>
          </motion.div>
        ))}
      </div>
    </div>
  );
}
